230: 	// highest Landlock ABI version that the kernel or xz supports.
231: 	//
232: 	// NOTE: LANDLOCK_ACCESS_FS_READ_DIR isn't needed here because
233: 	// the only input file has already been opened.
234: 	enable_landlock(0);
235: 	return;
236: }
