152: // Calls the given function once in a thread-safe way.
153: #define mythread_once(func) \
154: 	do { \
155: 		static pthread_once_t once_ = PTHREAD_ONCE_INIT; \
156: 		pthread_once(&once_, &func); \
157: 	} while (0)
