180: // Creates a new thread with all signals blocked. Returns zero on success
181: // and non-zero on error.
182: static inline int
183: mythread_create(mythread *thread, void *(*func)(void *arg), void *arg)
184: {
185: 	sigset_t old;
186: 	sigset_t all;
187: 	sigfillset(&all);
