259: 		int ret = pthread_condattr_setclock(
260: 				&condattr, CLOCK_MONOTONIC);
261: 		if (ret == 0)
262: 			ret = pthread_cond_init(&mycond->cond, &condattr);
263: 
264: 		pthread_condattr_destroy(&condattr);
265: 
266: 		if (ret == 0) {
267: 			mycond->clk_id = CLOCK_MONOTONIC;
268: 			return 0;
269: 		}
270: 	}
